const $=id=>document.getElementById(id);let demo=false,start=0,night=false,previous=null,muted=false,n=0,tries=0,last=Date.now();
const nags=[['ej','tak tylko patrzę czy już idziesz','no idę'],['nie no spoko','jutro wstaniesz siłą charakteru','mam dużo charakteru'],['halo łóżko tutaj','nie wiem czy pamiętasz ale mieszkamy razem','aaa faktycznie'],['ten film ma 38 minut','to nie jest „jeszcze chwilka”','na ×2 to 19'],['ziemniak zasnął','a ty dalej klikasz. nawet warzywo ogarnęło','nie porównuj nas'],['jest ktoś?','a szkoda. miało cię już tu nie być','to mój duch'],['jutro rano:','„czemu jestem taki zmęczony”\nno ciekawe kurde czemu','zagadka'],['psst','po drugiej stronie poduszki jest chłodno','mocny argument'],['aktualizacja','nic się nie zmieniło. dalej masz iść spać','dzięki za info']];
const excuses=['ale to jest bardzo ważny film o wydrach','jeszcze tylko naprawię jeden błąd','w Japonii jest już rano','nie mogę spać, ktoś się myli w internecie','ale ja wstałem dopiero niedawno','to nie scrollowanie tylko badania'];
const replies=['dobra wydry rozumiem. ale potem spać.','zapisz. zamknij. jutro będą dwa.','to śpij po japońsku','on jutro też będzie się mylił','a ziemniak w ogóle nie wstał i co','wynik badań: idź spać'];let ex=0,pokes=0;
function beep(){NightSounds.play('popup')}
function popup(data){if(muted)return;const m=data||nags[n%nags.length];n++;while($('popups').children.length>=3)$('popups').firstElementChild.remove();const el=document.createElement('aside');el.className='popup';el.style.right=(16+(n%3)*23)+'px';el.style.bottom=(65+(n%3)*58)+'px';el.style.transform='rotate('+((n%3-1)*3)+'deg)';el.innerHTML='<div class="bar"><span>wiadomość z łóżka</span><button aria-label="Zamknij">×</button></div><h2></h2><p></p><button class="ok"></button>';el.querySelector('h2').textContent=m[0];el.querySelector('p').textContent=m[1];el.querySelector('.ok').textContent=m[2];el.querySelectorAll('button').forEach(b=>b.onclick=()=>{el.remove();$('stop').classList.toggle('hidden',!$('popups').children.length)});$('popups').append(el);$('stop').classList.remove('hidden');beep()}
function quiet(){muted=true;$('popups').replaceChildren();$('stop').classList.add('hidden');$('quiet').textContent='pokaż okienka z powrotem';$('bubble').textContent='…'}
function tick(){const d=demo?new Date(2026,0,1,23,0,Math.floor((Date.now()-start)/1000)):new Date();night=d.getHours()>=23||d.getHours()<6;$('hm').textContent=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');$('ss').textContent=':'+String(d.getSeconds()).padStart(2,'0');if(previous!==night){document.body.classList.toggle('night',night);$('heading').textContent=night?'no już. do łóżka.':'jeszcze nie śpisz?';$('sub').textContent=night?'po 23. wszystko co teraz robisz można zrobić jutro.':'do 23 masz jeszcze chwilę. korzystaj mądrze. albo nie.';$('bubble').textContent=night?'a ty co tu jeszcze robisz':'ja to bym się już położył';last=Date.now()-10000;previous=night}if(night&&!muted&&Date.now()-last>13000){popup();last=Date.now()}}
function toggleTest(){demo=!demo;start=Date.now();previous=null;muted=false;$('popups').replaceChildren();$('stop').classList.add('hidden');$('quiet').textContent='schowaj okienka';NightSounds.play('test');tick()}
let testKeys='';document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat||e.target.closest('input,textarea,[contenteditable=true]'))return;if(e.key.length!==1){testKeys='';return}testKeys=(testKeys+e.key.toLowerCase()).slice(-4);if(testKeys==='test'){testKeys='';toggleTest()}});$('more').onclick=()=>{tries++;muted=false;$('count').textContent=tries===1?'dobra. ale to ostatnie 5.':`to już ${tries*5} dodatkowych minut. pięknie nam idzie.`;$('quiet').textContent='schowaj okienka';popup(['5 minut?',tries===1?'mhm. widzimy się za 5 minut z tym samym tekstem.':`kliknięcie nr ${tries}. ten przycisk nie zatrzymuje czasu, wiesz?`,'wiem wiem'])};$('potato').onclick=()=>{$('bubble').textContent=['nie dotykaj ziemniaka','on próbuje spać','ty też spróbuj','ej no','dobra teraz twoja kolej'][pokes++%5]};$('excuse').onclick=()=>{muted=false;popup([excuses[ex%excuses.length],replies[ex%replies.length],'no dobra']);ex++};$('quiet').onclick=()=>{if(muted){muted=false;$('quiet').textContent='schowaj okienka';$('bubble').textContent='o, jednak tęsknisz';last=Date.now()}else quiet()};$('stop').onclick=quiet;$('sleep').onclick=()=>{quiet();$('bye').showModal()};$('return').onclick=()=>$('bye').close();document.addEventListener('keydown',e=>{if(e.key==='Escape')quiet()});tick();setInterval(tick,500);
